function rrTrainCss(t){const h=rrLineColor(t);return h?rrPanelColor(h):rrCssServiceAccent(t.type)}
function rrTrainFill(t){const h=rrLineColor(t);return h?rrPanelColor(h):rrCssWhiteTextFill(t.type)}
