function rrDestText(t,isArrival){if(t.ring)return t.ring==='cw'?'Clockwise':'Anticlockwise';return isArrival?t.origin:t.dest}
// a ring train's direction icon (clockwise / anticlockwise, RR Info/UI) before its direction
function rrRingIcon(t){return t.ring?`<svg class="rr-action-icon rr-ring-icon" aria-hidden="true" focusable="false" viewBox="0 0 32 32"><use href="#rr-ui-${t.ring==='cw'?'clockwise':'anticlockwise'}"></use></svg>`:''}
// "via": the next main stations or interchanges (Mainline / Regio) the train calls at after this station (before it, for
